// hello.c
#include <stdio.h>

int main(void) {
    printf("hello, world\n");
    return 0;
}

# run each stage separately with gcc
gcc -E hello.c -o hello.i   # preprocess only
gcc -S hello.i              # compile to assembly: hello.s
gcc -c hello.s              # assemble to object file: hello.o
gcc hello.o -o hello        # link: executable 'hello'
./hello                     # the shell asks the OS to run it

long sum(long *a, long n) {
    long s = 0;
    for (long i = 0; i < n; i++)
        s += a[i];
    return s;
}
